// CompareMeasurement is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareMeasurement(before, after foundryvalue.Optional[Measurement], assigned MeasurementDraft) (MeasurementChanges, error) {
	before = foundryMeasurementSnapshot(before)
	after = foundryMeasurementSnapshot(after)
	var changes MeasurementChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.ID[Measurement](), before, after, assigned.fieldID.IsSet(), func(item Measurement) model.ID[Measurement] { return item.ID })
	if err != nil {
		return MeasurementChanges{}, fmt.Errorf("compare Measurement.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return MeasurementChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.UserID, err = lifecycle.CompareModelField(codec.ID[User](), before, after, assigned.fieldUserID.IsSet(), func(item Measurement) model.ID[User] { return item.UserID })
	if err != nil {
		return MeasurementChanges{}, fmt.Errorf("compare Measurement.UserID: %w", err)
	}
	changes.fields.Amount, err = lifecycle.CompareModelField(codec.Nullable(codec.Decimal()), before, after, assigned.fieldAmount.IsSet(), func(item Measurement) foundryvalue.Nullable[decimal.Decimal] { return item.Amount })
	if err != nil {
		return MeasurementChanges{}, fmt.Errorf("compare Measurement.Amount: %w", err)
	}
	changes.fields.Score, err = lifecycle.CompareModelField(codec.Nullable(codec.Float[float64]()), before, after, assigned.fieldScore.IsSet(), func(item Measurement) foundryvalue.Nullable[float64] { return item.Score })
	if err != nil {
		return MeasurementChanges{}, fmt.Errorf("compare Measurement.Score: %w", err)
	}
	changes.fields.Label, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldLabel.IsSet(), func(item Measurement) string { return item.Label })
	if err != nil {
		return MeasurementChanges{}, fmt.Errorf("compare Measurement.Label: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
func foundryMeasurementSnapshot(snapshot foundryvalue.Optional[Measurement]) foundryvalue.Optional[Measurement] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Measurement]{}
	}
	return foundryvalue.Set(Measurement{
		ID:     item.ID,
		UserID: item.UserID,
		Amount: item.Amount,
		Score:  item.Score,
		Label:  item.Label,
	})
}

